package com.hms.audit;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="audit_logs") public class AuditLog { @Id private UUID id; private UUID tenantId; @Column(nullable=false,length=120) private String action; @Column(nullable=false,length=120) private String entityType; @Column(length=120) private String entityId; @Column(length=1000) private String summary; @Column(nullable=false) private OffsetDateTime createdAt; protected AuditLog(){} public AuditLog(UUID tenantId,String action,String entityType,String entityId,String summary){this.id=UUID.randomUUID();this.tenantId=tenantId;this.action=action;this.entityType=entityType;this.entityId=entityId;this.summary=summary;this.createdAt=OffsetDateTime.now();} public UUID getId(){return id;} public String getAction(){return action;} public String getEntityType(){return entityType;} public String getEntityId(){return entityId;} public String getSummary(){return summary;} }
